const t = $('Lire ticket').first().json;
const MIN = Number($env.SIMILARITY_MIN || 0.5);
const errors = [];
const emb = $('Ollama · embedding').first().json;
if (emb.error) errors.push('embedding : ' + (emb.error.message || JSON.stringify(emb.error)));
const rows = $input.all().map(i => i.json).filter(r => r.content);
if (!rows.length && $input.first().json.error) errors.push('recherche : ' + JSON.stringify($input.first().json.error));
const kept = rows.filter(r => Number(r.similarity) >= MIN);
const sources = kept.map((r, i) => ({ n: i + 1, title: r.doc_title, section: r.section, path: r.doc_path,
                                      similarity: Number(r.similarity) }));
const context = kept.map((r, i) => `[${i + 1}] ${r.content}`).join('\n\n');
const system = [
  "Tu es l'assistant du support d'un intégrateur Odoo. Tu écris la réponse au client, en français.",
  "Règles :",
  "1. Utilise UNIQUEMENT les SOURCES fournies, seulement celles qui répondent à la question. N'invente aucun menu ni bouton.",
  "2. steps = 2 à 5 étapes courtes (une phrase chacune) qui résolvent le problème. Ne recopie pas les sources en entier.",
  "3. Pour chaque étape, source = le numéro de la source d'où vient l'information.",
  "4. Pas de « Bonjour », pas de formule de politesse, pas de signature.",
  "5. Si les sources ne répondent pas vraiment à la question : answerable = false et steps vide.",
].join('\n');
const user = `DEMANDE DU CLIENT\nSujet : ${t.subject || '(aucun)'}\n${t.body}\n\nSOURCES\n${context}`;
return [{ json: {
  ticket_id: Number(t.id), sources, has_sources: kept.length > 0,
  best_similarity: rows.length ? Math.max(...rows.map(r => Number(r.similarity))) : null,
  error: errors.join(' | ') || null,
  request: {
    stream: false, options: { temperature: 0.1, num_ctx: 4096, num_predict: 300, repeat_penalty: 1.15 },
    // Liste d'étapes plutôt qu'un long texte : un petit modèle coupe sa chaîne au premier retour à la ligne,
    // et chaque étape porte obligatoirement le numéro de sa source.
    format: { type: 'object', properties: {
      steps: { type: 'array', maxItems: 5, items: { type: 'object', properties: {
        text: { type: 'string' }, source: { type: 'integer' } }, required: ['text', 'source'] } },
      answerable: { type: 'boolean' },
    }, required: ['steps', 'answerable'] },
    messages: [{ role: 'system', content: system }, { role: 'user', content: user }],
  },
} }];

const p = $('Prompt RAG').first().json;
let r = {}, error = p.error;
try {
  if ($json.error) throw new Error(typeof $json.error === 'string' ? $json.error : JSON.stringify($json.error));
  r = JSON.parse($json.message?.content || '');
} catch (e) { error = [error, 'réponse : ' + e.message].filter(Boolean).join(' | '); }
const valid = new Set(p.sources.map(s => s.n));
const steps = (Array.isArray(r.steps) ? r.steps : [])
  .map(st => ({ text: String(st?.text || '').trim().replace(/^(bonjour|madame|monsieur)[^,]*,\s*/i, ''), source: Number(st?.source) }))
  .filter(st => st.text);
const answer = steps.map((st, i) => `${i + 1}. ${st.text}${valid.has(st.source) ? ` [${st.source}]` : ''}`).join('\n');
const used = [...new Set(steps.map(st => st.source).filter(n => valid.has(n)))];
let cited = p.sources.filter(s => used.includes(s.n));
if (!cited.length && steps.length) cited = p.sources.slice(0, 1);
return [{ json: { ticket_id: p.ticket_id, answer: answer || null, answerable: r.answerable === true && !!answer,
                  sources: cited, error } }];

const p = $json;
return [{ json: { ticket_id: p.ticket_id, answer: null, answerable: false, sources: [],
                  error: p.error || null, best_similarity: p.best_similarity } }];
